const $=s=>document.querySelector(s),titleScreen=$('#titleScreen'),gameScreen=$('#gameScreen'),scene=$('#scene'),storyText=$('#storyText'),speaker=$('#speaker'),choices=$('#choices'),tensionBar=$('#tensionBar'),clueCount=$('#clueCount'),cluesPanel=$('#cluesPanel'),cluesList=$('#cluesList'),ending=$('#ending'),endingTitle=$('#endingTitle'),endingText=$('#endingText');let state={step:0,tension:12,clues:[]};const clueData={clock:{title:'الساعة المتوقفة',text:'كل الساعات في الشقة توقفت عند 03:17، إلا ساعة هاتفك.'},voice:{title:'تسجيل صوتي',text:'صوت طفلة يهمس: لا تفتحي الباب. أنا في الداخل.'},photo:{title:'الصورة المبللة',text:'في الصورة أنتِ واقفة أمام هذا المبنى… لكن الصورة أُخذت قبل ولادتك.'}};const scenes=[{speaker:'الراوي',text:'استيقظتِ على اهتزاز هاتفك. لا اسم، لا رقم… فقط رسالة واحدة: «أخيراً عدتِ».',choices:[['افتحي الرسالة','open'],['اتركي الهاتف','ignore']]},{speaker:'الهاتف',text:'03:17 — «اسمعي جيداً. عندما يطرق الباب، لا تنظري من العين السحرية.»',choices:[['شغّلي التسجيل الصوتي','voice'],['احذفي الرسالة','delete']]},{speaker:'الراوي',text:'جاء الطرق من آخر الممر. ثلاث طرقات بطيئة. ثم صوت احتكاك شيء ثقيل بالأرض.',choices:[['اقتربي من الباب','door'],['اختبئي في الغرفة','hide']]},{speaker:'الراوي',text:'على الأرض صورة مبللة. ظهرها يحمل عنوان شقتك وتاريخاً: 17 أكتوبر 2004.',choices:[['التقطي الصورة','photo'],['اتركيها مكانها','leave']]},{speaker:'الصوت خلف الباب',text:'«أنا أعرف أنكِ تسمعينني. افتحي… أريد أن أريكِ أين تركتِني.»',choices:[['افتحي الباب','openDoor'],['اصعدي إلى السطح','roof']]}];function addClue(id){if(!state.clues.includes(id)){state.clues.push(id);clueCount.textContent=state.clues.length;renderClues()}}function renderClues(){cluesList.innerHTML=state.clues.map(id=>`<div class="clue"><strong>${clueData[id].title}</strong><p>${clueData[id].text}</p></div>`).join('')||'<p class="panel-note">لم تجمعي أي دليل بعد.</p>'}function setTension(n){state.tension=Math.max(5,Math.min(100,state.tension+n));tensionBar.style.width=state.tension+'%'}function render(){if(state.step>=scenes.length)return finish();const s=scenes[state.step];speaker.textContent=s.speaker;storyText.textContent=s.text;choices.innerHTML='';s.choices.forEach(([label,id])=>{const b=document.createElement('button');b.className='choice';b.textContent=label;b.onclick=()=>choose(id);choices.appendChild(b)});if(state.step===4)$('#chapterTitle').textContent='السطح'}function choose(id){choices.innerHTML='';setTension(['ignore','delete','hide','leave'].includes(id)?-3:8);if(id==='voice')addClue('voice');if(id==='photo')addClue('photo');if(id==='open')addClue('clock');if(id==='roof')scene.className='scene scene-rooftop';state.step++;state.step<scenes.length?render():finish()}function finish(){ending.classList.remove('hidden');const brave=state.tension>55&&state.clues.length>=2;endingTitle.textContent=brave?'من خلف الباب':'السطح لا ينام';endingText.textContent=brave?'فتحتِ الباب. لم يكن هناك أحد، لكن هاتفك بدأ يصوّر من تلقاء نفسه. في الشاشة، رأيتِ نفسكِ واقفة خلفكِ. ثم وصلتك رسالة جديدة: «الآن دورك أن تطرقي».':'هربتِ إلى السطح حتى طلع الفجر. عندما نظرتِ إلى الأسفل، كانت نافذة شقتك مضاءة… وظلكِ يلوّح لكِ من الداخل.'}function start(){titleScreen.classList.add('hidden');gameScreen.classList.remove('hidden');state={step:0,tension:12,clues:[]};clueCount.textContent='0';renderClues();setTension(0);render()}$('#startBtn').onclick=start;$('#restartBtn').onclick=()=>{ending.classList.add('hidden');start()};$('#cluesBtn').onclick=()=>cluesPanel.classList.remove('hidden');$('#closeClues').onclick=()=>cluesPanel.classList.add('hidden');$('#soundBtn').onclick=e=>e.currentTarget.textContent=e.currentTarget.textContent==='◒'?'◌':'◒';document.addEventListener('keydown',e=>{if(e.key==='Escape')cluesPanel.classList.add('hidden')});
